parameters.jsCode:
let candidateText = $input.item.json.candidates[0].content.parts[0].text;
const inputData = $('Prepare Builder Input').item.json;

// Slack Block Kit character limit is 3,000 per section block
if (candidateText.length > 2600) {
  candidateText = candidateText.substring(0, 2600) + '\n\n*(Full blueprint truncated to fit Slack character limit)*';
}

const slackPayload = {
  response_type: "in_channel",
  text: `🚀 *Nova Assistant - Feature Command Processed*`,
  blocks: [
    {
      "type": "header",
      "text": {
        "type": "plain_text",
        "text": "🚀 Nova Feature Request Processed",
        "emoji": true
      }
    },
    {
      "type": "section",
      "fields": [
        { "type": "mrkdwn", "text": `*Requested By:*\n@${inputData.user_name}` },
        { "type": "mrkdwn", "text": `*Instruction:*\n"${inputData.user_text}"` }
      ]
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": `*🤖 Nova AI Plan & Implementation:*\n${candidateText}`
      }
    },
    {
      "type": "context",
      "elements": [
        {
          "type": "mrkdwn",
          "text": "⚡ Nova Cloud Engine • Deployed live on https://automation.lesterlabs.cloud"
        }
      ]
    }
  ]
};

return {
  json: {
    response_url: inputData.response_url,
    slack_payload: slackPayload
  }
};
